// @nodegx:generated by `nodegx export --target html` — Story/Paster.
import { batch, value } from '../lib/core.js';
import { bindText, el, life, truthy, when } from '../lib/dom.js';

/**
 * Paste a story
 *
 * Draws into `element` (before `before`, when given). `inputs` are what the parent sets:
 * `value`, `problem`, and the callbacks `onPlay`, `onBack`.
 * Returns `update(inputs)` to change them, `outputs`, and `destroy()` to take it off the page.
 */
export function mountPaster(element, inputs = {}, before) {
  const l = life();
  const given = Object.assign({}, inputs);
  const input = { value: value(inputs['value']), problem: value(inputs['problem']) };
  const state = {
    theStoryAsText: value(''), // The input's local state (§4c) — the graph path syncs it without firing Changed; the user path writes it and runs the Changed chain.
  };

  const paWrap = el(element, 'div', 'Paster-paWrap', undefined, before);
  const paBox = el(paWrap, 'textarea', 'Paster-paBox story-paste');
  paBox.placeholder = 'Paste a list of passages here…';
  l.run(function () {
    const text = state.theStoryAsText.get();
    if (paBox.value !== text) paBox.value = text;
  });
  paBox.addEventListener('input', function () {
    state.theStoryAsText.set(paBox.value);
  });
  // What is wrong with it: on the page while its Mounted is true.
  when(l, paWrap, function () {
    const on = input.problem.get();
    return on === undefined ? true : truthy(on);
  }, function (into, at, l) {
    const paProblem = el(into, 'p', 'Paster-paProblem', undefined, at);
    bindText(l, paProblem, function () { return input.problem.get(); });
    return paProblem;
  });
  const paRow = el(paWrap, 'div', 'Paster-paRow');
  const paPlay = el(paRow, 'button', 'Paster-paPlay pressable', 'Read this story');
  paPlay.type = 'button';
  paPlay.addEventListener('click', function () {
    if (given.onPlay) given.onPlay();
  });
  const paBack = el(paRow, 'button', 'Paster-paBack pressable', 'Back to reading');
  paBack.type = 'button';
  paBack.addEventListener('click', function () {
    if (given.onBack) given.onBack();
  });

  return {
    update(next) {
      Object.assign(given, next);
      batch(function () {
        if ('value' in next) input.value.set(next['value']);
        if ('problem' in next) input.problem.set(next['problem']);
      });
    },
    outputs: {},
    destroy() {
      l.destroy();
      paWrap.remove();
    }
  };
}
